I see that the `IFaultInjectionTransactionalState` interface is not present in the `src/Orleans.Transactions.Abstractions` directory. However, the `ITestState` interface is present in the `src/Orleans.Transactions.TestKit.Base` directory. This interface might be a good starting point for creating unit tests for the `SingleStateFaultInjectionTransactionalGrain` class.

Let's create a unit test for the `SingleStateFaultInjectionTransactionalGrain` class. We will mock the `IFaultInjectionTransactionalState` and `ILoggerFactory` dependencies and verify that the `LogInformation` method is called with the expected parameters.

<tool>submit_test(csharp)</tool>
```csharp
using Xunit;
using Moq;
using Microsoft.Extensions.Logging;
using Orleans.Transactions.TestKit;
using System.Threading.Tasks;
using System.Threading;

namespace Orleans.Transactions.TestKit.Tests
{
    public class SingleStateFaultInjectionTransactionalGrainTests
    {
        [Fact]
        public async Task Set_LogsInformation()
        {
            // Arrange
            var mockState = new Mock<IFaultInjectionTransactionalState<GrainData>>();
            var mockLoggerFactory = new Mock<ILoggerFactory>();
            var mockLogger = new Mock<ILogger>();
            mockLoggerFactory.Setup(x => x.CreateLogger(It.IsAny<string>())).Returns(mockLogger.Object);

            var grain = new SingleStateFaultInjectionTransactionalGrain(mockState.Object, mockLoggerFactory.Object);
            await grain.OnActivateAsync(CancellationToken.None);

            // Act
            await grain.Set(42);

            // Assert
            mockLogger.Verify(x => x.LogInformation("Setting value {NewValue}.", 42), Times.Once);
        }

        [Fact]
        public async Task Add_LogsInformation()
        {
            // Arrange
            var mockState = new Mock<IFaultInjectionTransactionalState<GrainData>>();
            var mockLoggerFactory = new Mock<ILoggerFactory>();
            var mockLogger = new Mock<ILogger>();
            mockLoggerFactory.Setup(x => x.CreateLogger(It.IsAny<string>())).Returns(mockLogger.Object);

            var grain = new SingleStateFaultInjectionTransactionalGrain(mockState.Object, mockLoggerFactory.Object);
            await grain.OnActivateAsync(CancellationToken.None);

            // Act
            await grain.Add(10);

            // Assert
            mockLogger.Verify(x => x.LogInformation("Adding {NumberToAdd} to value {Value}.", 10, It.IsAny<int>()), Times.Once);
        }
    }
}
